import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

final class UndirectedGraphFactory {

    private UndirectedGraphFactory() {
    }

    static UndirectedGraph fromEdgeList(int vertexCount, int[][] edges) {
        validateGraphInput(vertexCount, edges);

        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
        for (int i = 0; i < vertexCount; i++) {
            adjacencyList.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            validateEdge(edge);

            int source = edge[0];
            int target = edge[1];
            validateVertex(source, vertexCount);
            validateVertex(target, vertexCount);

            adjacencyList.get(source).add(target);
            adjacencyList.get(target).add(source);
        }

        List<List<Integer>> frozenAdjacencyList = new ArrayList<>(vertexCount);
        for (List<Integer> neighbors : adjacencyList) {
            frozenAdjacencyList.add(List.copyOf(neighbors));
        }

        return new UndirectedGraph(vertexCount, frozenAdjacencyList);
    }

    private static void validateGraphInput(int vertexCount, int[][] edges) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }
        Objects.requireNonNull(edges, "edges");
    }

    private static void validateEdge(int[] edge) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two vertices");
        }
    }

    private static void validateVertex(int vertex, int vertexCount) {
        if (vertex < 0 || vertex >= vertexCount) {
            throw new IllegalArgumentException(
                    "Vertex " + vertex + " is out of bounds for graph size " + vertexCount);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;

final class BipartiteAnalyzer {

    private BipartiteAnalyzer() {
    }

    static boolean isBipartite(GraphView graph) {
        Objects.requireNonNull(graph, "graph");

        Coloring coloring = new Coloring(graph.vertexCount());

        for (int startVertex = 0; startVertex < coloring.size(); startVertex++) {
            if (coloring.isUncolored(startVertex) && !colorComponent(startVertex, graph, coloring)) {
                return false;
            }
        }

        return true;
    }

    private static boolean colorComponent(int startVertex, GraphView graph, Coloring coloring) {
        Deque<Integer> queue = new ArrayDeque<>();
        coloring.assign(startVertex, Partition.LEFT);
        queue.addLast(startVertex);

        while (!queue.isEmpty()) {
            int currentVertex = queue.removeFirst();
            Partition currentPartition = coloring.partitionOf(currentVertex);
            Partition oppositePartition = currentPartition.opposite();

            for (int neighbor : graph.neighborsOf(currentVertex)) {
                if (coloring.isUncolored(neighbor)) {
                    coloring.assign(neighbor, oppositePartition);
                    queue.addLast(neighbor);
                    continue;
                }

                if (coloring.partitionOf(neighbor) == currentPartition) {
                    return false;
                }
            }
        }

        return true;
    }

    private enum Partition {
        LEFT,
        RIGHT;

        Partition opposite() {
            return this == LEFT ? RIGHT : LEFT;
        }
    }

    private static final class Coloring {
        private final Partition[] partitions;

        private Coloring(int vertexCount) {
            this.partitions = new Partition[vertexCount];
        }

        int size() {
            return partitions.length;
        }

        boolean isUncolored(int vertex) {
            return partitions[vertex] == null;
        }

        Partition partitionOf(int vertex) {
            return partitions[vertex];
        }

        void assign(int vertex, Partition partition) {
            partitions[vertex] = partition;
        }
    }
}

import java.util.List;

final class UndirectedGraph implements GraphView {

    private final int vertexCount;
    private final List<List<Integer>> adjacencyList;

    UndirectedGraph(int vertexCount, List<List<Integer>> adjacencyList) {
        this.vertexCount = vertexCount;
        this.adjacencyList = List.copyOf(adjacencyList);
    }

    @Override
    public int vertexCount() {
        return vertexCount;
    }

    @Override
    public List<Integer> neighborsOf(int vertex) {
        return adjacencyList.get(vertex);
    }
}

